/**
 * Bare-invocation status block (AXI "content first").
 *
 * A bare `superdesign` (no subcommand) is invoked mostly by AI agents. Per the
 * Agent eXperience Interface (https://axi.md), it prints live, actionable state
 * instead of a full commander help dump: the resolved executable path, a
 * one-line description + version, the LOCAL auth state, a small bounded block of
 * live project data (when authenticated and the fetch succeeds), and a
 * contextual `help[N]:` block of concrete next-step command templates. The
 * builders here are pure so they can be unit-tested without touching the
 * filesystem or network - the live fetch happens in the caller and is passed in.
 */
/** A compact project record for the content-first live-data block. */
export interface BareStatusProject {
    id: string;
    name: string;
}
export interface BareStatusInput {
    /** Resolved CLI version (from CLI_VERSION, not package.json). */
    version: string;
    /** Whether local credentials are present. Derived from config only. */
    authenticated: boolean;
    /** Team name from local config, when authenticated. */
    teamName?: string;
    /** Absolute path of the local credential store, shown as a hint. */
    configPath?: string;
    /** `~`-compressed path of the resolved CLI executable (AXI `bin:` line). */
    binPath?: string;
    /**
     * Bounded, most-recent-first project list for the live-data block. `undefined`
     * means "no live data" (unauthenticated, fetch failed, or fetch skipped) and
     * the block degrades away gracefully. An empty array renders a definitive
     * empty state.
     */
    projects?: BareStatusProject[];
    /** Total recent projects available, when more than are shown (aggregate). */
    projectTotal?: number;
}
/**
 * One global disclosure that `--json` exists, so it stays discoverable without
 * being repeated in every per-command hint (which recommend the default AXI
 * output). Reused by the top-level `--help` footer.
 */
export declare const JSON_GLOBAL_NOTE = "note: append --json to any command for the full machine-readable payload.";
/** Human/agent-readable status block. Terse, well under 30 lines. */
export declare function buildBareStatus(input: BareStatusInput): string;
/** Machine-readable status for `superdesign --json` (no subcommand). */
export declare function buildBareStatusJson(input: BareStatusInput): string;
